node --input-type=module -e '
import assert from "node:assert/strict";
import { Writable } from "node:stream";
import { pipeline } from "node:stream/promises";
const events = [];
const sink = new Writable({
  write(chunk, encoding, done) { setImmediate(() => done(new Error("sink failed"))); }
});
await assert.rejects(pipeline(async function* ({ signal }) {
  try {
    yield Buffer.from("first");
    await new Promise((resolve, reject) => {
      const onAbort = () => { events.push("source aborted"); reject(signal.reason); };
      if (signal.aborted) onAbort();
      else signal.addEventListener("abort", onAbort, { once: true });
    });
  } finally { events.push("source finalized"); }
}, sink), /sink failed/);
assert.deepEqual(events, ["source aborted", "source finalized"]);
assert.equal(sink.destroyed, true);
console.log(JSON.stringify({ node: process.version, events, sinkDestroyed: sink.destroyed }));
'

