import { exportCsv } from './export.mjs';
export async function download(request, { authorize, api }) {
  const tenantId = await authorize(request.session, request.tenantId);
  const csv = await exportCsv({ tenantId }, api);
  return { status: 200, contentType: 'text/csv', body: csv };
}
export function health() { return { status: 'ok' }; }

src/export.mjs.content:
export async function exportCsv({ tenantId }, api) {
  const rows = [];
  let cursor = null;
  let snapshot = null;
  do {
    const page = await api.list({ tenantId, cursor, snapshot });
    snapshot = page.snapshot;
    cursor = page.next_cursor;
    for (const item of page.items) rows.push([item.id, item.label]);
  } while (cursor !== null);
  return 'id,label\n' + rows.map(row => row.map(quoteCsv).join(',')).join('\n');
}
function quoteCsv(value) { return '"' + String(value).replaceAll('"', '""') + '"'; }

