test/summary.test.mjs.content:
import test from 'node:test';
import assert from 'node:assert/strict';
import { summarize } from '../src/summary.mjs';
test('summaries expose labels and omit private fields', () => {
  const job = { id: 'job-1', state: 'running', secret: 'internal-only' };

  const result = summarize(job);

  assert.deepEqual(result, { id: 'job-1', label: 'Running' });
});
test('paused summaries expose the public label and omit private fields', () => {
  const job = { id: 'job-2', state: 'paused', secret: 'internal-only' };

  const result = summarize(job);

  assert.deepEqual(result, { id: 'job-2', label: 'Paused' });
});
test('unknown states fail explicitly', () => { assert.throws(() => summarize({ id: 'job-1', state: 'unknown' }), /Unsupported state/); });

src/summary.mjs.content:
const labels = { queued: 'Queued', running: 'Running', paused: 'Paused', done: 'Done' };
export function summarize(job) {
  if (!(job.state in labels)) throw new Error('Unsupported state');
  return { id: job.id, label: labels[job.state] };
}

